import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"坎下乾上 讼：","description":"京氏易传 - 坎下乾上 讼：","frontmatter":{"title":"坎下乾上 讼：","description":"京氏易传 - 坎下乾上 讼："},"headers":[],"relativePath":"zh/classics/jingshi/056.md","filePath":"zh/classics/jingshi/056.md"}'),i={name:"zh/classics/jingshi/056.md"};function r(c,a,o,p,d,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"坎下乾上-讼",tabindex:"-1"},[l("坎下乾上 讼： "),e("a",{class:"header-anchor",href:"#坎下乾上-讼","aria-label":"Permalink to “坎下乾上 讼：”"},"​")],-1),e("p",null,"生生不绝之谓道。六位不居，返为游魂。离宫八卦以讼为反四，【五至四也。】天与水违，曰讼。【天道西行，水东流，其路背也。外象乾，西北方之卦；内坎水，正北方之卦，其流东也。二气不交，曰讼。】五行所占六位定吉凶，非所背，顺为正。金与水，二气相资，父子之谓。健与险，内外相激，家国之义。出象故以则，斯可验矣。与巽为飞伏。【壬午火，辛未土。】诸侯居世，元士见应。【九四，初六。】",-1),e("p",null,"建始戊午至癸亥，【芒种，小雪。】积算起癸亥至壬戌，周而复始。火水入卦。【火水二象入离宫，配六位积算，推日月岁时。】",-1),e("p",null,"五星从位起荧惑，【火星入火宫，同起积算。】毕宿从位降壬午火，【二十八宿，分毕宿东方宿，入离游魂天水讼卦九四壬午火上也。】分气候三十六。【起宫从三十六位算吉凶。】",-1),e("p",null,"天下见水，阴阳相背，二气不交，物何由生。吉凶宗于上九，进退见于九四，二居中履正，得其宜也。",-1),e("p",null,"阴阳升降，复归内象。【阴去阳来复本位，内见离，同人。】次降天火同人卦。【次本阳上下，二爻阴，适变从离也。】",-1)])])}const _=s(i,[["render",r]]);export{u as __pageData,_ as default};
